const $=id=>document.getElementById(id);
purposeMarkup();
const defaults={...purposeDefaults,project:'Explorer rover',part:'plate',length:160,width:110,thickness:4,hole:4,material:'PLA',mission:'remote',board:'uno',current:800,runtime:2};
let state={...defaults},mesh=[],angle=.62,tilt=.65,zoom=1,active='purpose';
function valid(raw){
 const s={...defaults}; if(!raw||typeof raw!=='object')return s;
 for(const k of Object.keys(s)){
  if(typeof s[k]==='number'){
   const spec=fieldSpecs[k],range=partRanges[k]||(k==='legs'?[4,6]:spec?.slice(1,3));
   if(raw[k]!==undefined&&raw[k]!==''&&Number.isFinite(+raw[k])&&range){s[k]=Math.min(range[1],Math.max(range[0],+raw[k]));if(spec?.[3]===1)s[k]=Math.round(s[k]);if(k==='legs')s[k]=s[k]>=5?6:4;}
  }else if(k==='project'){if(typeof raw[k]==='string')s[k]=raw[k].slice(0,80);}
  else{const choices={family:Object.keys(families),part:Object.keys(partNames),material:['PLA','PETG','ABS'],mission:['remote','avoid','line'],board:['uno','esp32','pico'],task:fieldSpecs.task[1],terrain:fieldSpecs.terrain[1]};if(choices[k]?.includes(raw[k]))s[k]=raw[k];}
 }
 if(!families[s.family].parts.includes(s.part))s.part=families[s.family].parts[0];
 // Leave wall stock around the square holes on narrow parts.
 s.hole=Math.min(s.hole,Math.min(s.width,s.length)/2-2);
 if(s.part==='bracket')s.thickness=Math.min(s.thickness,s.length-3,s.width-3);
 return s;
}
try{state=valid(JSON.parse(localStorage.getItem('robot-factory-v1')||'{}'))}catch{}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),2600)}
function save(){try{localStorage.setItem('robot-factory-v1',JSON.stringify(state));$('saved').textContent='● Saved on this device'}catch{$('saved').textContent='Storage unavailable · export to save'}}
function download(name,data,type='text/plain'){const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000)}
function tab(name){active=name;document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===name));document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===name));$('breadcrumb').textContent={purpose:'Robot purpose',design:'Design studio',electronics:'Electronics',code:'Code generator',guide:'Build guide'}[name];if(name==='design')draw()}
document.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>tab(x.dataset.tab));
function sync(){for(const k in defaults)$(k).value=state[k];update()}
for(const k in defaults)$(k).addEventListener('input',()=>{if(typeof defaults[k]==='number'&&!$(k).validity.valid)return;state[k]=typeof defaults[k]==='number'?+$(k).value:$(k).value;state=valid(state);save();update()});
function quad(a,b,c,d){mesh.push([a,b,c],[a,c,d])}
function makeMesh(){mesh=[];const L=state.length,W=state.width,T=state.thickness,H=state.hole;
 if(state.part==='wheel'){const n=96,ro=L/2,ri=H/2;for(let i=0;i<n;i++){let a=i*2*Math.PI/n,b=((i+1)%n)*2*Math.PI/n;let p=(r,t,z)=>[r*Math.cos(t),r*Math.sin(t),z];quad(p(ro,a,0),p(ro,b,0),p(ro,b,T),p(ro,a,T));quad(p(ri,b,0),p(ri,a,0),p(ri,a,T),p(ri,b,T));quad(p(ri,a,T),p(ro,a,T),p(ro,b,T),p(ri,b,T));quad(p(ri,b,0),p(ro,b,0),p(ro,a,0),p(ri,a,0));}return;}
 // An extruded grid with shared vertices gives a closed plate with four square through-holes.
 let xs,ys,filled;
 if(state.part==='plate'){const inset=Math.min(12,L/4,W/4);xs=[-L/2,-L/2+inset-H/2,-L/2+inset+H/2,L/2-inset-H/2,L/2-inset+H/2,L/2];ys=[-W/2,-W/2+inset-H/2,-W/2+inset+H/2,W/2-inset-H/2,W/2-inset+H/2,W/2];filled=(i,j)=>i>=0&&j>=0&&i<5&&j<5&&!([1,3].includes(i)&&[1,3].includes(j));}
 else{xs=[-L/2,-L/2+T,L/2];ys=[0,T,W];filled=(i,j)=>i>=0&&j>=0&&i<2&&j<2&&(i===0||j===0);}
 for(let i=0;i<xs.length-1;i++)for(let j=0;j<ys.length-1;j++)if(filled(i,j)){let x=xs[i],X=xs[i+1],y=ys[j],Y=ys[j+1];let a=[x,y,0],b=[X,y,0],c=[X,Y,0],d=[x,Y,0],e=[x,y,T],f=[X,y,T],g=[X,Y,T],h=[x,Y,T];quad(a,d,c,b);quad(e,f,g,h);if(!filled(i,j-1))quad(a,b,f,e);if(!filled(i+1,j))quad(b,c,g,f);if(!filled(i,j+1))quad(c,d,h,g);if(!filled(i-1,j))quad(d,a,e,h);}
 // Stand the L profile upright, extruded to 24 mm depth.
 if(state.part==='bracket')mesh=mesh.map(tri=>tri.map(([x,y,z])=>[x,z/T*24-12,y]).reverse());
}
function normal(t){let [a,b,c]=t,u=b.map((v,i)=>v-a[i]),v=c.map((v,i)=>v-a[i]);return[u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]]}
function volume(){return Math.abs(mesh.reduce((sum,[a,b,c])=>sum+(a[0]*(b[1]*c[2]-b[2]*c[1])+a[1]*(b[2]*c[0]-b[0]*c[2])+a[2]*(b[0]*c[1]-b[1]*c[0]))/6,0))}
const boards={uno:{name:'Arduino Uno R3',pins:[7,8,5,9,10,6],logic:'5 V',sensor:'A0 / A1'},esp32:{name:'ESP32 DevKit',pins:[18,19,25,21,22,26],logic:'3.3 V',sensor:'GPIO 32 / 33'},pico:{name:'Raspberry Pi Pico',pins:[2,3,4,6,7,8],logic:'3.3 V',sensor:'GP26 / GP27'}};
function rows(){const b=boards[state.board];return[[b.name,'1','Controller · '+b.logic+' logic'],['Dual H-bridge motor driver','1','2 direction + 1 PWM input per motor'],['Matched geared DC motors','2','Choose torque and voltage for your load'],['Regulated logic supply','1','Match controller input requirements'],['Battery, switch & fuse','1 set','Match motor voltage and stall current'],...(state.mission==='avoid'?[['Distance sensor','1','Logic-compatible interface; calibrate stopping distance']]:state.mission==='line'?[['Reflectance sensors','2','Analog outputs within controller ADC voltage']]:[['USB serial connection','1','Tethered manual control; radio not included']])];}
function firmware(){const b=boards[state.board],p=b.pins;
if(state.board==='uno')return `// Robot Factory | Arduino Uno R3 | Arduino AVR core\n// Dual H-bridge: IN1, IN2, PWM per channel. See wiring map.\n// Serial 115200: F forward, B back, L left, R right, S stop.\n// Send commands repeatedly; watchdog stops after 500 ms.\n// Mission: ${state.mission}. Sensor/autonomy logic is not included.\nconst int A1_PIN=${p[0]}, A2_PIN=${p[1]}, A_PWM=${p[2]};\nconst int B1_PIN=${p[3]}, B2_PIN=${p[4]}, B_PWM=${p[5]};\nconst int SPEED=90;\nunsigned long lastCommand=0;\nvoid motor(int in1,int in2,int pwm,int speed) {\n  analogWrite(pwm,0);\n  digitalWrite(in1,speed>0 ? HIGH : LOW);\n  digitalWrite(in2,speed<0 ? HIGH : LOW);\n  analogWrite(pwm,abs(speed));\n}\nvoid drive(int left,int right) {\n  motor(A1_PIN,A2_PIN,A_PWM,left);\n  motor(B1_PIN,B2_PIN,B_PWM,right);\n}\nvoid setup() {\n  int pins[]={A1_PIN,A2_PIN,A_PWM,B1_PIN,B2_PIN,B_PWM};\n  for(int pin:pins) pinMode(pin,OUTPUT);\n  drive(0,0);\n  Serial.begin(115200);\n}\nvoid loop() {\n  if(Serial.available()) {\n    char cmd=Serial.read();\n    if(cmd=='F') drive(SPEED,SPEED);\n    else if(cmd=='B') drive(-SPEED,-SPEED);\n    else if(cmd=='L') drive(-SPEED,SPEED);\n    else if(cmd=='R') drive(SPEED,-SPEED);\n    else if(cmd=='S') drive(0,0);\n    if(cmd=='F'||cmd=='B'||cmd=='L'||cmd=='R'||cmd=='S') lastCommand=millis();\n  }\n  if(millis()-lastCommand>500) drive(0,0);\n}\n`;
return `# Robot Factory | ${b.name} | MicroPython\n# Pins use GPIO numbers, not physical header positions.\n# USB REPL: F/B/L/R/S then Enter. Repeat within 500 ms.\n# Mission: ${state.mission}. Sensor/autonomy logic not included.\nfrom machine import Pin, PWM\nimport sys, select, time\n\na1, a2 = Pin(${p[0]}, Pin.OUT, value=0), Pin(${p[1]}, Pin.OUT, value=0)\nb1, b2 = Pin(${p[3]}, Pin.OUT, value=0), Pin(${p[4]}, Pin.OUT, value=0)\npa, pb = PWM(Pin(${p[2]})), PWM(Pin(${p[5]}))\nfor pwm in (pa, pb):\n    pwm.freq(1000)\n    pwm.duty_u16(0)\n\ndef motor(i1, i2, pwm, speed):\n    pwm.duty_u16(0)\n    i1.value(speed > 0)\n    i2.value(speed < 0)\n    pwm.duty_u16(int(abs(speed) * 65535))\n\ndef drive(left, right):\n    motor(a1, a2, pa, left)\n    motor(b1, b2, pb, right)\n\npoll = select.poll()\npoll.register(sys.stdin, select.POLLIN)\ncommands = {'F': (0.35, 0.35), 'B': (-0.35, -0.35),\n            'L': (-0.35, 0.35), 'R': (0.35, -0.35), 'S': (0, 0)}\nlast_command = time.ticks_ms()\ntry:\n    drive(0, 0)\n    while True:\n        if poll.poll(0):\n            command = sys.stdin.read(1).upper()\n            if command in commands:\n                drive(*commands[command])\n                last_command = time.ticks_ms()\n        if time.ticks_diff(time.ticks_ms(), last_command) > 500:\n            drive(0, 0)\n        time.sleep_ms(5)\nfinally:\n    drive(0, 0)\n    pa.deinit()\n    pb.deinit()\n`;
}
function update(){const wheel=state.part==='wheel',bracket=state.part==='bracket';$('lLabel').textContent=wheel?'Outer diameter':'Length';$('wLabel').textContent=bracket?'Upright height':'Width';$('width').closest('.field').style.display=wheel?'none':'';$('hole').closest('.field').style.display=bracket?'none':'';$('hLabel').textContent=wheel?'Axle bore diameter':'Mounting hole (square)';for(let k of ['length','width','thickness','hole'])$(k+'Out').textContent=state[k]+' mm';$('partTitle').textContent=$('part').selectedOptions[0].textContent;$('partHint').textContent=wheel?'96-sided wheel with a circular through-bore. Add a tire for traction.':bracket?'Solid L profile, 24 mm deep. Drill mounting holes to fit your hardware.':'Four square through-holes, inset 12 mm from the edges. Dimensions in millimeters.';makeMesh();$('bounds').textContent=`${state.length} × ${wheel?state.length:bracket?24:state.width} × ${bracket?state.width:state.thickness}`;$('mass').textContent=(volume()/1000*{PLA:1.24,PETG:1.27,ABS:1.04}[state.material]).toFixed(1)+' g';draw();$('requirements').replaceChildren(...rows().map(([name,qty,desc])=>{const r=document.createElement('div');r.className='req';const d=document.createElement('div');const title=document.createElement('b');title.textContent=name;const info=document.createElement('small');info.textContent=desc;d.append(title,document.createElement('br'),info);const q=document.createElement('span');q.textContent='× '+qty;r.append(d,q);return r}));$('battery').textContent=`Capacity target: ${Math.ceil(state.current*state.runtime*1.25)} mAh at your system supply voltage. Estimate = ${state.current} mA × ${state.runtime} h × 1.25. Conversion losses and motor stall peaks need separate checks.`;const b=boards[state.board];$('wiring').innerHTML='<table><thead><tr><th>Driver signal</th><th>Controller pin</th><th>Purpose</th></tr></thead><tbody>'+['AIN1','AIN2','PWMA','BIN1','BIN2','PWMB'].map((s,i)=>`<tr><td>${s}</td><td>${state.board==='uno'?'D':'GPIO '}${b.pins[i]}</td><td>${i%3===2?'Speed (PWM)':'Direction'}</td></tr>`).join('')+'</tbody></table>';$('filename').textContent=state.board==='uno'?'robot_factory.ino':'main.py';$('codeDescription').textContent=b.name+' · '+(state.board==='uno'?'Arduino C++':'MicroPython')+' · dual motor serial control';$('source').textContent=firmware();}
function draw(){const c=$('canvas'),r=c.getBoundingClientRect();if(!r.width)return;const dpr=window.devicePixelRatio||1;c.width=r.width*dpr;c.height=r.height*dpr;let ctx=c.getContext('2d');ctx.scale(dpr,dpr);const scale=Math.min(r.width/Math.max(300,state.length*1.6),r.height/Math.max(250,state.width*1.5))*zoom;const centerZ=state.part==='bracket'?state.width/2:0;function project([x,y,z]){let u=x*Math.cos(angle)-y*Math.sin(angle),v=x*Math.sin(angle)+y*Math.cos(angle);return[r.width/2+u*scale,r.height/2+22+(v*Math.sin(tilt)-(z-centerZ)*Math.cos(tilt))*scale,v*Math.cos(tilt)+(z-centerZ)*Math.sin(tilt)]}ctx.save();ctx.translate(r.width/2,r.height/2+65);ctx.scale(1,.35);let g=ctx.createRadialGradient(0,0,10,0,0,120*scale);g.addColorStop(0,'#4b59352b');g.addColorStop(1,'#4b593500');ctx.fillStyle=g;ctx.fillRect(-180*scale,-180*scale,360*scale,360*scale);ctx.restore();let faces=mesh.map(t=>({t,p:t.map(project)})).sort((a,b)=>a.p.reduce((s,p)=>s+p[2],0)-b.p.reduce((s,p)=>s+p[2],0));for(let {t,p} of faces){const n=normal(t),mag=Math.hypot(...n);let light=Math.abs((n[0]*.2+n[1]*-.4+n[2]*.8)/mag);ctx.fillStyle=`rgb(${Math.round(128+light*36)},${Math.round(143+light*36)},${Math.round(99+light*35)})`;ctx.beginPath();ctx.moveTo(...p[0].slice(0,2));ctx.lineTo(...p[1].slice(0,2));ctx.lineTo(...p[2].slice(0,2));ctx.closePath();ctx.fill();ctx.strokeStyle=ctx.fillStyle;ctx.lineWidth=.5;ctx.stroke();}ctx.fillStyle='#7f8b70';ctx.font='10px monospace';ctx.fillText(state.length+' mm',r.width/2+45,r.height-65)}
let pointer=null;$('canvas').onpointerdown=e=>{pointer=[e.clientX,e.clientY];$('canvas').setPointerCapture(e.pointerId)};$('canvas').onpointermove=e=>{if(!pointer)return;angle+=(e.clientX-pointer[0])*.009;tilt=Math.max(.15,Math.min(1.45,tilt+(e.clientY-pointer[1])*.007));pointer=[e.clientX,e.clientY];draw()};$('canvas').onpointerup=$('canvas').onpointercancel=()=>pointer=null;$('canvas').addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.5,Math.min(2,zoom-e.deltaY*.001));draw()},{passive:false});$('reset').onclick=()=>{angle=.62;tilt=.65;zoom=1;draw()};new ResizeObserver(draw).observe($('canvas'));
$('stl').onclick=()=>{let stl='solid robot_factory\n';for(const t of mesh){let n=normal(t),m=Math.hypot(...n);stl+=`facet normal ${n.map(v=>v/m).join(' ')}\n outer loop\n${t.map(p=>'  vertex '+p.join(' ')).join('\n')}\n endloop\nendfacet\n`;}download(state.part+'.stl',stl+'endsolid robot_factory\n','model/stl');toast('STL exported · import in millimeters')};
$('export').onclick=()=>{download('robot-factory-project.json',JSON.stringify({version:2,...state},null,2),'application/json');toast('Project exported')};$('new').onclick=()=>{if(confirm('Start a new project? Export your current project first if you want to keep it.')){state={...defaults,project:'Untitled robot'};sync();save();tab('purpose')}};$('bom').onclick=()=>download('robot-factory-bom.csv','Component,Quantity,Requirement\n'+rows().map(row=>row.map(v=>'"'+v.replaceAll('"','""')+'"').join(',')).join('\n'),'text/csv');$('downloadCode').onclick=()=>download($('filename').textContent,firmware());$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(firmware());toast('Code copied')}catch{toast('Clipboard unavailable. Download the code instead.')}};$('importButton').onclick=()=>$('import').click();$('import').onchange=async e=>{try{const raw=JSON.parse(await e.target.files[0].text());if(![1,2].includes(raw.version)||!raw.board||!raw.part)throw Error();state=valid(raw);sync();save();toast('Project imported');tab('purpose')}catch{toast('Invalid project file. Choose a Robot Factory export.')}e.target.value=''};
const originalMesh=makeMesh,roverRows=rows,roverFirmware=firmware,originalUpdate=update;
makeMesh=purposeMesh;rows=purposeRows;firmware=purposeFirmware;
update=function(){
 const options=families[state.family].parts;
 if($('part').dataset.family!==state.family){$('part').replaceChildren(...options.map(id=>{const o=document.createElement('option');o.value=id;o.textContent=partNames[id];return o}));$('part').dataset.family=state.family;}
 $('part').value=state.part;
 originalUpdate();purposeSummary();purposePartUI();purposeHardwareUI();
};
initPurpose();
